interface User { id: string; name: string; }

function isUser(value: unknown): value is User {
  return typeof value === 'object' && value !== null
    && 'id' in value && typeof (value as User).id === 'string'
    && 'name' in value && typeof (value as User).name === 'string';
}

function greet(raw: unknown) {
  if (!isUser(raw)) throw new Error('invalid user');
  return raw.name;
}

function assertIsString(value: unknown): asserts value is string {
  if (typeof value !== 'string') throw new TypeError('Expected string');
}

function upper(raw: unknown) {
  assertIsString(raw);
  return raw.toUpperCase();
}

type Shape = { kind: 'circle'; r: number } | { kind: 'rect'; w: number; h: number };

function area(s: Shape) {
  if (s.kind === 'circle') return Math.PI * s.r ** 2;
  return s.w * s.h;
}

string Describe(object o) => o switch {
    string s => s,
    int n => n.ToString(),
    _ => "unknown"
};
